local archive=game:GetService("HttpService"):JSONDecode([====[{"revision":"bb8c60bdfac1fff1f77669b918c2b34da14cfad0","namespace":"_RigStudyArchive_bb8c60b","sources":{"client/HollowClock":"local Lighting = game:GetService(\"Lighting\")\n\nlocal Clock = {}\n-- A shared world timezone, fixed year-round. This is a real 24-hour day.\nClock.TimeZoneOffsetHours = -5\n\nfunction Clock.sample(unixSeconds)\n\tlocal hour = (unixSeconds / 3600 + Clock.TimeZoneOffsetHours) % 24\n\tlocal sunlight = math.clamp((math.sin((hour - 6) * math.pi / 12) + 0.08) / 0.6, 0, 1)\n\treturn hour, sunlight * sunlight * (3 - 2 * sunlight)\nend\n\nfunction Clock.environment(unixSeconds)\n\tlocal hour, daylight = Clock.sample(unixSeconds)\n Clock.lastHour,Clock.lastDaylight=hour,daylight\n\tLighting.ClockTime = hour\n\tLighting.Brightness = 1.0 + 1.13 * daylight\n\tLighting.ExposureCompensation = 0.13 * (1 - daylight)\n\tLighting.Ambient = Color3.fromHex(\"#7D948C\"):Lerp(Color3.fromHex(\"#99927A\"), daylight)\n\tLighting.OutdoorAmbient = Color3.fromHex(\"#869E95\"):Lerp(Color3.fromHex(\"#9CA598\"), daylight)\n\tLighting.ColorShift_Top = Color3.fromHex(\"#BBCFE1\"):Lerp(Color3.fromHex(\"#FFF4E5\"), daylight)\n\tlocal air = Lighting:FindFirstChildOfClass(\"Atmosphere\")\n\tif air then\n\t\tair.Color = Color3.fromHex(\"#99B6B4\"):Lerp(Color3.fromHex(\"#D3E6F0\"), daylight)\n\t\tair.Decay = Color3.fromHex(\"#748E8C\"):Lerp(Color3.fromHex(\"#DCC69D\"), daylight)\n\t\tair.Density = 0.18 + daylight * 0.02\n\tend\n\tlocal grade = Lighting:FindFirstChild(\"SproutHollowGrade\")\n\tif grade then\n\t\tgrade.TintColor = Color3.fromHex(\"#DDECE6\"):Lerp(Color3.fromHex(\"#FFF5E5\"), daylight)\n\tend\n return hour,daylight\nend\nfunction Clock.daylight()return Clock.lastDaylight or select(2,Clock.sample(workspace:GetServerTimeNow()))end\nClock.Step=5\nlocal Controller={};Controller.__index=Controller\nlocal function finite(value)return type(value)==\"number\"and value==value and math.abs(value)<math.huge end\nfunction Controller:paint(light,record)\n if not light.Parent or light:GetAttribute(\"HollowLamp\")~=true then return end\n local day,night=light:GetAttribute(\"HollowDayBrightness\"),light:GetAttribute(\"HollowNightBrightness\")\n day=if finite(day)and day>=0 then day else .65\n night=if finite(night)and night>=0 then night else 1.55\n local brightness=night+(day-night)*self.daylight\n -- Native Brightness is float32; repeated equal sky samples must not issue\n -- setters merely because an authored numeric attribute is a Lua double.\n local delta=math.abs(light.Brightness-brightness)\n if record.desired~=brightness or delta>1e-5 then\n  record.desired=brightness\n  if delta>1e-5 then light.Brightness=brightness;self.writes+=1 end\n end\nend\nfunction Controller:track(item)\n if not item:IsA(\"PointLight\")or self.lights[item]then return end\n local record={connections={}};self.lights[item]=record\n for _,name in ipairs({\"HollowLamp\",\"HollowDayBrightness\",\"HollowNightBrightness\"})do\n  table.insert(record.connections,item:GetAttributeChangedSignal(name):Connect(function()\n   if not self.destroyed and self.lights[item]==record then self:paint(item,record)end\n  end))\n end\n self:paint(item,record)\nend\nfunction Controller:remove(item)\n local record=self.lights[item];if not record then return end\n self.lights[item]=nil;for _,c in ipairs(record.connections)do c:Disconnect()end\nend\nfunction Controller:bind(room)\n if self.room==room then return end\n for _,c in ipairs(self.roomConnections)do c:Disconnect()end;table.clear(self.roomConnections)\n for light in pairs(self.lights)do self:remove(light)end\n self.room=room;if not room then return end\n table.insert(self.roomConnections,room.DescendantAdded:Connect(function(item)if not self.destroyed and self.room==room then self:track(item)end end))\n table.insert(self.roomConnections,room.DescendantRemoving:Connect(function(item)if not self.destroyed and self.room==room then self:remove(item)end end))\n self.scans+=1;for _,item in ipairs(room:GetDescendants())do self:track(item)end\nend\nfunction Controller:apply(unixSeconds)\n local hour,daylight=Clock.sample(unixSeconds);self.daylight=daylight\n self.environment(unixSeconds)\n for light,record in pairs(self.lights)do self:paint(light,record)end\n self.samples+=1;return hour,daylight\nend\nfunction Controller:step(dt)\n if self.destroyed then return end\n self.elapsed+=dt;if self.elapsed<Clock.Step then return end\n self.elapsed%=Clock.Step;self:apply(self.now())\nend\nfunction Controller:stats()\n local count,managed=0,0;for light in pairs(self.lights)do count+=1;if light:GetAttribute(\"HollowLamp\")==true then managed+=1 end end\n return {lights=count,managed=managed,connections=#self.connections+#self.roomConnections+count*3,scans=self.scans,samples=self.samples,writes=self.writes}\nend\nfunction Controller:getStats()return self:stats()end\nfunction Controller:destroy()\n if self.destroyed then return end;self.destroyed=true\n self:bind(nil);for _,c in ipairs(self.connections)do c:Disconnect()end;table.clear(self.connections)\n if self.ownsBloom and self.bloom then self.bloom:Destroy()end\n if Clock.controller==self then Clock.controller=nil;Clock.started=false end\nend\nfunction Clock.new(options)\n options=options or {};local world=options.world or workspace\n local self=setmetatable({world=world,now=options.now or function()return workspace:GetServerTimeNow()end,\n  environment=options.environment or Clock.environment,lights={},connections={},roomConnections={},elapsed=0,writes=0,samples=0,scans=0,daylight=select(2,Clock.sample((options.now or function()return workspace:GetServerTimeNow()end)()))},Controller)\n table.insert(self.connections,world.ChildAdded:Connect(function(item)if not self.destroyed and item.Name==\"EggDropLounge\"then self:bind(item)end end))\n table.insert(self.connections,world.ChildRemoved:Connect(function(item)if not self.destroyed and self.room==item then self:bind(nil)end end))\n self:bind(world:FindFirstChild(\"EggDropLounge\"));self:apply(self.now())\n if options.auto then table.insert(self.connections,game:GetService(\"RunService\").Heartbeat:Connect(function(dt)self:step(dt)end))end\n return self\nend\nfunction Clock.apply(unixSeconds)\n if Clock.controller and not Clock.controller.destroyed then return Clock.controller:apply(unixSeconds)end\n return Clock.environment(unixSeconds)\nend\nfunction Clock.start()\n if Clock.controller and not Clock.controller.destroyed then return Clock.controller end\n local controller=Clock.new({auto=true});Clock.controller,Clock.started=controller,true\n local bloom=Lighting:FindFirstChild(\"HollowBloom\")\n if not bloom then\n  bloom=Instance.new(\"BloomEffect\");bloom.Name,bloom.Intensity,bloom.Size,bloom.Threshold=\"HollowBloom\",.12,12,1.4;bloom.Parent=Lighting;controller.ownsBloom=true\n end\n controller.bloom=bloom;return controller\nend\nreturn Clock\n","client/PetFactory":"-- Common aliases preserve profile identity while selecting the new authored babies.\nlocal Factory={}\nfunction Factory.new(parent,origin,pet,worldScale,appearance)\n if pet.id==\"pip\"or pet.id==\"puddle\"then return require(script.Parent.PetPoseSampler).attach(require(script.Parent.GardenPetVisual).new(parent,origin,pet,worldScale,appearance))end\n local family=pet.family or pet.id\n local module=if family==\"pip\"then script.Parent.PipVisual elseif family==\"puddle\"then script.Parent.PuddleVisual else script.Parent.BonusPetVisual\n local visual=require(module).new(parent,origin,pet,worldScale)\n return require(script.Parent.PetPoseSampler).attach(require(script.Parent.LegacyPetAppearance).attach(visual,pet,appearance))\nend\nfunction Factory.create(parent,origin,pet,masteryMask,rank,legacy,appearance)\n local visual=Factory.new(parent,origin,pet,.72,appearance)\n require(script.Parent.PetPrestige).attach(visual,pet,rank or 0,legacy)\n return visual\nend\nreturn Factory\n","client/PetPrestige":"-- Retired live progression. Archived profile facts remain available to cosmetics.\nlocal Prestige={}\nfunction Prestige.read(_board,_pet)return 0,false end\nfunction Prestige.attach(visual,_pet,_rank,_legacy)\n    visual.model:SetAttribute(\"MasteryRank\",0)\n    visual.model:SetAttribute(\"LegacyMasteryFinish\",false)\nend\nfunction Prestige.updateBadge(_visual,_camera)end\nfunction Prestige.crestReserve(_visual)return 0 end\nfunction Prestige.update(_visual,_dt,_reduced)end\nreturn Prestige\n","client/LegacyPetAppearance":"-- Explicit role adapter for the five existing collection silhouettes.\n-- Rare petals, flame cores, moons and every face part retain authored identity.\nlocal Shared=game:GetService(\"ReplicatedStorage\")._RigStudyArchive_bb8c60b.Shared\nlocal Palette=require(Shared.PetPalette)\nlocal Hue=require(Shared.HueCatalog)\nlocal Charms=require(script.Parent.PetCharms)\nlocal Face=require(script.Parent.PetFace)\nlocal Adapter={}\nlocal roles={\n bloom_pip={main={Body=true,Flipper=true},secondary={Slipper=true,SprigStem=true,WideLeaf=true,NewLeaf=true,LeafPixel=true},anchor=Vector3.new(0,3.65,0)},\n wick={main={Body=true,Foot=true},secondary={Flame=true},anchor=Vector3.new(0,3.20,0)},\n orbit={main={Body=true,Foot=true},secondary={OrbitRing=true},anchor=Vector3.new(0,2.48,0)},\n foxfire_wick={main={Body=true,Foot=true},secondary={Foxfire=true},anchor=Vector3.new(0,3.30,0)},\n eclipse_orbit={main={Body=true,Foot=true},secondary={OrbitRing=true},anchor=Vector3.new(0,2.48,0)},\n}\nfunction Adapter.attach(visual,pet,appearance)\n local mapping=assert(roles[pet.id],\"Missing legacy color role map\")\n visual.petId=pet.id;visual.colors=Palette.resolve(pet.id,appearance);visual.secondaryColor=visual.colors.secondary\n visual.model:SetAttribute(\"HueAdapter\",pet.id);visual.model:SetAttribute(\"RigBackend\",\"LegacyNative\")\n for _,entry in ipairs(visual.pieces)do\n  local name=entry.part.Name;entry.name=name;entry.color=entry.part.Color;entry.originalColor=entry.part.Color\n  entry.colorRole=if mapping.main[name]then \"body\"elseif mapping.secondary[name]then \"secondary\"else nil\n  entry.faceBaseMaterial=entry.part.Material\n end\n local dot=Instance.new(\"Part\");dot.Name=\"CharmDot\";dot.Shape=Enum.PartType.Ball;dot.Anchored=true;dot.CanCollide=false;dot.CanTouch=false;dot.CanQuery=false;dot.Material=Enum.Material.SmoothPlastic;dot.Parent=visual.model\n local original=Palette.original(pet.id);local size=Vector3.new(.24,.31,.24)\n local entry={part=dot,name=\"CharmDot\",role=\"charm\",colorRole=\"secondary\",size=size,frame=CFrame.new(mapping.anchor),offset=CFrame.new(mapping.anchor),color=original.secondary,originalColor=original.secondary,faceBaseMaterial=dot.Material}\n table.insert(visual.pieces,entry)\n function visual:applyAppearance(value)\n  self.appearance=value or {};self.colors=Palette.resolve(pet.id,self.appearance);self.secondaryColor=self.colors.secondary\n  for _,item in ipairs(self.pieces)do if item.colorRole then\n   local doses=self.appearance[if item.colorRole==\"body\"then \"mainDoses\"else \"secondaryDoses\"]\n   local target=doses and Hue.resolveTarget(doses);local strength=doses and Hue.doseStrength(doses)or 0\n   item.color=if target then Palette.tint(item.originalColor,target,strength)else item.originalColor\n   if item.role==\"charm\"then item.color=self.secondaryColor end\n   item.part.Color=item.color\n  end end\n  Charms.apply(self,self.appearance);self.poseDirty=true\n end\n local update=visual.update\n function visual:update(dt)\n  update(self,dt)\n  for _,item in ipairs(self.pieces)do\n   if item.colorRole then Face.paintSurface(item,self,Face.daylight())end\n   if item.role==\"charm\"then item.part.Transparency=if self.charmVisible then 0 else 1 end\n  end\n end\n visual:applyAppearance(appearance);return visual\nend\nreturn Adapter\n","shared/HueCatalog":"-- Canonical paid pigments and free learned recipes. Stable IDs remain saved.\nlocal Hue={Cost=8,MaxRank=3,Supported={pip=true,puddle=true,wick=true,orbit=true,bloom_pip=true,foxfire_wick=true,eclipse_orbit=true},LegacySupported={pip=true,puddle=true},Weights={0,.65,.84,1},CatalogVersion=\"hue-items-v1\",MaxDose=5,StackLimit=9007199254740000}\nHue.Order={\n {id=\"rose\",name=\"Rose\",direction=\"Rose\",color=Color3.fromHex(\"#FF327A\"),cost=8},\n {id=\"tide\",name=\"Tide\",direction=\"Tide\",color=Color3.fromHex(\"#008DFF\"),cost=8},\n {id=\"citrus\",name=\"Citrus\",direction=\"Citrus\",color=Color3.fromHex(\"#FFCC00\"),cost=8},\n {id=\"iris\",name=\"Iris\",direction=\"Iris\",color=Color3.fromHex(\"#9350FF\"),cost=8},\n}\nHue.ById={};for _,item in ipairs(Hue.Order)do Hue.ById[item.id]=item end\nHue.MixOrder={\"rose:tide\",\"citrus:rose\",\"iris:rose\",\"citrus:tide\",\"iris:tide\",\"citrus:iris\"}\nHue.Mixes={\n [\"rose:tide\"]={a=\"rose\",b=\"tide\",name=\"Rose + Tide\",color=Color3.fromHex(\"#AC4BFA\")},\n [\"citrus:rose\"]={a=\"citrus\",b=\"rose\",name=\"Rose + Citrus\",color=Color3.fromHex(\"#FF733A\")},\n [\"iris:rose\"]={a=\"iris\",b=\"rose\",name=\"Rose + Iris\",color=Color3.fromHex(\"#E333BE\")},\n [\"citrus:tide\"]={a=\"citrus\",b=\"tide\",name=\"Tide + Citrus\",color=Color3.fromHex(\"#00BE77\")},\n [\"iris:tide\"]={a=\"iris\",b=\"tide\",name=\"Tide + Iris\",color=Color3.fromHex(\"#5859F1\")},\n [\"citrus:iris\"]={a=\"citrus\",b=\"iris\",name=\"Citrus + Iris\",color=Color3.fromHex(\"#EE6997\")},\n}\nfunction Hue.pair(a,b)\n if not Hue.ById[a]or not Hue.ById[b]or a==b then return nil end\n return if a<b then a..\":\"..b else b..\":\"..a\nend\nfunction Hue.get(hues,petId)\n local row=type(hues)==\"table\"and hues[petId]\n local ranks={};for _,item in ipairs(Hue.Order)do ranks[item.id]=if row and row.ranks then row.ranks[item.id]or 0 else 0 end\n return{ranks=ranks,body=if row then row.body else \"original\",secondary=if row then row.secondary else \"default\",mix=if row then row.mix else nil}\nend\nfunction Hue.appearance(hues,petId,petHues)\n local row=Hue.get(hues,petId);local mix=Hue.Mixes[row.mix]\n local result={body=row.body,bodyRank=if mix then math.min(row.ranks[mix.a],row.ranks[mix.b])else row.ranks[row.body]or 0,secondary=row.secondary,bodyMix=row.mix}\n local doses=petHues and petHues[petId]\n if doses then result.mainDoses=table.clone(doses.main);result.secondaryDoses=table.clone(doses.secondary)end\n return result\nend\nfunction Hue.capacity(state)\n for pet in pairs(Hue.Supported)do\n  local Eggs=require(script.Parent.EggCatalog)\n  if Eggs.isOwned(state.inventoryMask or 0,pet)then\n   local row=Hue.get(state.hues,pet)\n   for _,item in ipairs(Hue.Order)do if row.ranks[item.id]<Hue.MaxRank then return true end end\n  end\n end\n return false\nend\nHue.ItemOrder={\"rose\",\"tide\",\"citrus\",\"iris\",\"reset\"}\nHue.Items={};for _,h in ipairs(Hue.Order)do Hue.Items[h.id]={id=h.id,name=h.name..\" fruit\",color=h.color,weight=20}end\nHue.Items.reset={id=\"reset\",name=\"Reset Hue\",color=Color3.fromHex(\"#D4F8FF\"),weight=20}\nHue.DoseWeights={0,.44,.65,.84,.93,1}\nfunction Hue.emptyCounts()return{rose=0,tide=0,citrus=0,iris=0}end\nfunction Hue.validCounts(v)\n if type(v)~=\"table\"then return false end\n for k in pairs(v)do if not Hue.ById[k]then return false end end\n for _,h in ipairs(Hue.Order)do local n=v[h.id];if type(n)~=\"number\"or n~=n or n%1~=0 or n<0 or n>5 then return false end end\n return true\nend\nfunction Hue.equalCounts(a,b)\n if not Hue.validCounts(a)or not Hue.validCounts(b)then return false end\n for _,h in ipairs(Hue.Order)do if a[h.id]~=b[h.id]then return false end end;return true\nend\nfunction Hue.doseStrength(counts)\n local maximum=0;for _,h in ipairs(Hue.Order)do maximum=math.max(maximum,counts[h.id]or 0)end\n return Hue.DoseWeights[maximum+1]or 0\nend\nlocal setAnchors={}\nlocal function setKey(ids)local sorted=table.clone(ids);table.sort(sorted);return table.concat(sorted,\":\")end\nfor _,h in ipairs(Hue.Order)do setAnchors[h.id]=h.color end\nfor key,m in pairs(Hue.Mixes)do setAnchors[key]=m.color end\nfor key,hex in pairs({[\"citrus:rose:tide\"]=\"#F45688\",[\"iris:rose:tide\"]=\"#A64FFF\",[\"citrus:iris:rose\"]=\"#F059A5\",[\"citrus:iris:tide\"]=\"#35A9CD\",[\"citrus:iris:rose:tide\"]=\"#C963D9\"})do setAnchors[key]=Color3.fromHex(hex)end\nlocal function linear(c)return if c<=.04045 then c/12.92 else ((c+.055)/1.055)^2.4 end\nlocal function srgb(c)return if c<=.0031308 then c*12.92 else 1.055*c^(1/2.4)-.055 end\nfunction Hue.resolveTarget(counts)\n if not Hue.validCounts(counts)then return nil end\n local r,g,b,total=0,0,0,0\n for level=1,5 do\n  local ids={};for _,h in ipairs(Hue.Order)do if counts[h.id]>=level then table.insert(ids,h.id)end end\n  if #ids>0 then local c=setAnchors[setKey(ids)];local weight=#ids;r+=linear(c.R)*weight;g+=linear(c.G)*weight;b+=linear(c.B)*weight;total+=weight end\n end\n if total==0 then return nil end\n return Color3.new(srgb(r/total),srgb(g/total),srgb(b/total))\nend\nfunction Hue.roll(unit)\n if type(unit)~=\"number\"or unit~=unit or unit<0 or unit>=1 then return nil end\n return Hue.ItemOrder[math.min(5,math.floor(unit*5)+1)]\nend\nfunction Hue.mappedCounts(row,channel,preset)\n local counts=Hue.emptyCounts();local mapping={2,3,5}\n if channel==\"secondary\"then if Hue.ById[preset]and row.ranks[preset]>0 then counts[preset]=5;return counts end\n elseif Hue.ById[preset]and row.ranks[preset]>0 then counts[preset]=mapping[row.ranks[preset]];return counts\n elseif Hue.Mixes[preset]then local mix=Hue.Mixes[preset];local rank=math.min(row.ranks[mix.a],row.ranks[mix.b]);if rank>0 then counts[mix.a],counts[mix.b]=mapping[rank],mapping[rank];return counts end end\n return nil\nend\nfunction Hue.presets(hues,petId)\n local row=Hue.get(hues,petId);local result={main={},secondary={}}\n for _,h in ipairs(Hue.Order)do if row.ranks[h.id]>0 then\n  table.insert(result.main,{id=h.id,name=h.name,counts=Hue.mappedCounts(row,\"main\",h.id)})\n  table.insert(result.secondary,{id=h.id,name=h.name,counts=Hue.mappedCounts(row,\"secondary\",h.id)})\n end end\n for _,key in ipairs(Hue.MixOrder)do local counts=Hue.mappedCounts(row,\"main\",key);if counts then table.insert(result.main,{id=key,name=Hue.Mixes[key].name,counts=counts})end end\n return result\nend\nreturn Hue\n","shared/EggCatalog":"local Pets = require(script.Parent.PetCatalog)\n\nlocal Catalog = {\n\tDailyBonus = 6,\n\tDayOffsetSeconds = -5 * 3600,\n\tRareGuarantee = 7,\n\tOrder = { \"meadow\" },\n\tById = {\n\t\tmeadow = {\n\t\t\tname = \"Mixed Meadow\", cost = 18, color = Color3.fromHex(\"#C2EC74\"),\n\t\t\tweights = {\n\t\t\t\t{ id = \"pip\", weight = 35 }, { id = \"puddle\", weight = 25 },\n\t\t\t\t{ id = \"wick\", weight = 20 }, { id = \"orbit\", weight = 10 },\n\t\t\t\t{ id = \"bloom_pip\", weight = 5 }, { id = \"foxfire_wick\", weight = 3 },\n\t\t\t\t{ id = \"eclipse_orbit\", weight = 2 },\n\t\t\t},\n\t\t},\n\t\tsprout = {\n\t\t\tretired = true,\n\t\t\tname = \"Sprout Focused\", cost = 24, color = Color3.fromHex(\"#FFB77A\"),\n\t\t\tweights = { { id = \"pip\", weight = 80 }, { id = \"bloom_pip\", weight = 20 } },\n\t\t},\n\t},\n\tFamilies = { \"pip\", \"puddle\", \"wick\", \"orbit\" },\n}\n\nfunction Catalog.family(id)\n\tlocal pet = Pets.byId[id]\n\treturn pet and (pet.family or pet.id) or nil\nend\n\nfunction Catalog.bit(id)\n\tlocal pet = Pets.byId[id]\n\treturn if pet then bit32.lshift(1, pet.index - 1) else 0\nend\n\nfunction Catalog.isOwned(mask, id)\n\tlocal bit = Catalog.bit(id)\n\treturn bit ~= 0 and bit32.band(mask or 0, bit) ~= 0\nend\n\nfunction Catalog.mask(ids)\n\tlocal mask = 0\n\tfor _, id in ipairs(ids) do mask = bit32.bor(mask, Catalog.bit(id)) end\n\treturn mask\nend\n\nfunction Catalog.odds(recipeId, misses)\n\tlocal recipe = Catalog.ById[recipeId]\n\tif not recipe then return {} end\n\tlocal guarantee = (misses or 0) >= Catalog.RareGuarantee\n\tlocal total = 0\n\tfor _, entry in ipairs(recipe.weights) do\n\t\tif not guarantee or Pets.byId[entry.id].trial then total += entry.weight end\n\tend\n\tlocal odds = {}\n\tfor _, entry in ipairs(recipe.weights) do\n\t\tif not guarantee or Pets.byId[entry.id].trial then\n\t\t\ttable.insert(odds, { id = entry.id, weight = entry.weight / total * 100 })\n\t\tend\n\tend\n\treturn odds\nend\n\nfunction Catalog.roll(recipeId, misses, unit)\n\tassert(type(unit) == \"number\" and unit >= 0 and unit < 1, \"Random sample must be in [0, 1)\")\n\tlocal odds = Catalog.odds(recipeId, misses)\n\tassert(#odds > 0, \"Unknown egg recipe\")\n\tlocal threshold = unit * 100\n\tlocal cumulative = 0\n\tfor _, entry in ipairs(odds) do\n\t\tcumulative += entry.weight\n\t\tif threshold < cumulative then return entry.id end\n\tend\n\treturn odds[#odds].id\nend\n\nreturn Catalog\n","shared/PetCatalog":"local Trials = require(script.Parent.PocketTrials)\n\nlocal Pets = {\n\t{ id = \"pip\", name = \"Zivvi\", charge = 6, cue = \"pet\", color = Color3.fromHex(\"#E5DBD0\") },\n\t{ id = \"puddle\", name = \"Ovelle\", charge = 12, cue = \"puddle\", color = Color3.fromHex(\"#D3DBD9\") },\n\t{ id = \"wick\", name = \"Wick\", charge = 24, cue = \"wick\", color = Color3.fromHex(\"#F79860\") },\n\t{ id = \"orbit\", name = \"Orbit\", charge = 36, cue = \"orbit\", color = Color3.fromHex(\"#C7AEF3\") },\n}\n\nPets.rares = {\n\t{ id = \"bloom_pip\", name = \"Bloom Pip\", family = \"pip\", trial = Trials.HighRoller,\n\t\tcue = \"pet\", color = Color3.fromHex(\"#F6A786\") },\n\t{ id = \"foxfire_wick\", name = \"Foxfire Wick\", family = \"wick\", trial = Trials.Fivefold,\n\t\tcue = \"wick\", color = Color3.fromHex(\"#8EAEFF\"), accent = Color3.fromHex(\"#54EDDC\") },\n\t{ id = \"eclipse_orbit\", name = \"Eclipse Orbit\", family = \"orbit\", trial = Trials.DoubleSweep,\n\t\tcue = \"orbit\", color = Color3.fromHex(\"#7162C8\"), accent = Color3.fromHex(\"#FFD07E\") },\n}\nPets.collection = table.clone(Pets)\nfor _, pet in ipairs(Pets.rares) do\n\ttable.insert(Pets.collection, pet)\nend\nPets.byId = {}\nfor index, pet in ipairs(Pets.collection) do\n\tpet.index = index\n\tPets.byId[pet.id] = pet\nend\n\nfunction Pets.isUnlocked(pet, rank, trials, inventoryMask)\n\tif inventoryMask ~= nil then\n\t\treturn bit32.band(inventoryMask, bit32.lshift(1, pet.index - 1)) ~= 0\n\tend\n\tif pet.trial then\n\t\treturn bit32.band(trials, pet.trial.bit) ~= 0\n\tend\n\treturn pet.index <= rank\nend\n\nfunction Pets.ownedCount(rank, trials, inventoryMask)\n\tif inventoryMask ~= nil then\n\t\tlocal count = 0\n\t\tfor _, pet in ipairs(Pets.collection) do\n\t\t\tif Pets.isUnlocked(pet, rank, trials, inventoryMask) then count += 1 end\n\t\tend\n\t\treturn count\n\tend\n\tlocal count = math.min(rank, #Pets)\n\tfor _, pet in ipairs(Pets.rares) do\n\t\tif Pets.isUnlocked(pet, rank, trials) then\n\t\t\tcount += 1\n\t\tend\n\tend\n\treturn count\nend\n\nreturn Pets\n","shared/PocketTrials":"local highRoller = { bit = 2, name = \"High Roller\", hint = \"Score 250 in one round\", target = 250, readout = \"Points\" }\nlocal fivefold = { bit = 8, name = \"Fivefold\", hint = \"Chain 5 merges\", target = 5, readout = \"Chain\" }\nlocal doubleSweep = {\n\tbit = 16, name = \"Double Sweep\", hint = \"Clear 2 tier V pairs in one round\", target = 2, readout = \"Tier V pairs\",\n}\nlocal Trials = {\n\tGoals = {\n\t\t{ bit = 1, name = \"Triple Pop\", hint = \"Chain 3 merges\", target = 3 },\n\t\thighRoller,\n\t\t{ bit = 4, name = \"Clean Sweep\", hint = \"Merge two tier V jellies\", target = 1 },\n\t},\n\tClubMask = 7,\n\tRareMask = 24,\n\tAll = 31,\n\tHighRoller = highRoller,\n\tFivefold = fivefold,\n\tDoubleSweep = doubleSweep,\n}\n\nfunction Trials.mask(value)\n\treturn if type(value) == \"number\" and value >= 0 and value <= Trials.All and value == math.floor(value)\n\t\tthen value else 0\nend\n\nfunction Trials.clubComplete(mask)\n\treturn bit32.band(mask, Trials.ClubMask) == Trials.ClubMask\nend\n\nfunction Trials.earned(mask, chain, score, clears)\n\treturn bit32.bor(mask, if chain >= Trials.Goals[1].target then 1 else 0,\n\t\tif score >= highRoller.target then highRoller.bit else 0, if clears >= 1 then 4 else 0,\n\t\tif chain >= fivefold.target then fivefold.bit else 0, if clears >= doubleSweep.target then doubleSweep.bit else 0)\nend\n\nreturn Trials\n","shared/PetPalette":"local Definitions=require(script.Parent.PetRigDefinitions)\nlocal Hue=require(script.Parent.HueCatalog)\nlocal Palette={}\nlocal legacy={\n bloom_pip={body=\"#F6A786\",secondary=\"#74B971\"},wick={body=\"#F79860\",secondary=\"#F6C557\"},orbit={body=\"#C7AEF3\",secondary=\"#806BBA\"},\n foxfire_wick={body=\"#8EAEFF\",secondary=\"#54EDDC\"},eclipse_orbit={body=\"#7162C8\",secondary=\"#FFD07E\"},\n}\nfunction Palette.original(petId)\n local def=Definitions[petId];local source=if def then def.palette else legacy[petId]\n if not source then return nil end\n local result={};for role,hex in pairs(source)do result[role]=Color3.fromHex(hex)end\n if not def then result.face=Color3.fromHex(\"#392846\");result.mouth=result.face;result.ivory=Color3.fromHex(\"#FFF6E9\");result.blush=Color3.fromHex(\"#F4D2F5\")end\n return result\nend\nlocal function linear(c)return if c<=.04045 then c/12.92 else ((c+.055)/1.055)^2.4 end\nlocal function srgb(c)return if c<=.0031308 then c*12.92 else 1.055*c^(1/2.4)-.055 end\nfunction Palette.tint(base,target,weight)\n local function channel(a,b)return srgb(linear(a)*(1-weight)+linear(b)*weight)end\n return Color3.new(channel(base.R,target.R),channel(base.G,target.G),channel(base.B,target.B))\nend\nfunction Palette.resolve(petId,appearance)\n local result=Palette.original(petId);if not result then return nil end\n local token=if type(appearance)==\"table\"then appearance else {}\n local hue=Hue.Mixes[token.bodyMix]or Hue.ById[token.body];local rank=token.bodyRank\n if hue and type(rank)==\"number\"and rank%1==0 and rank>=1 and rank<=3 then result.body=Palette.tint(result.body,hue.color,Hue.Weights[rank+1])end\n local secondary=Hue.ById[token.secondary];if secondary then result.secondary=secondary.color end\n for _,channel in ipairs({{\"mainDoses\",\"body\"},{\"secondaryDoses\",\"secondary\"}})do\n  local counts=token[channel[1]]\n  if Hue.validCounts(counts)then local original=Palette.original(petId)[channel[2]];local target=Hue.resolveTarget(counts);result[channel[2]]=if target then Palette.tint(original,target,Hue.doseStrength(counts))else original end\n end\n return table.freeze(result)\nend\nreturn Palette\n","shared/PetRigDefinitions":"-- Authored by Astra in Blender; garden-size geometry, +Z front and paws origin.\nlocal definitions=game:GetService(\"HttpService\"):JSONDecode([=[{\"pip\":{\"schema\":1,\"id\":\"zivvi\",\"legacyId\":\"pip\",\"axes\":{\"up\":\"+Y\",\"front\":\"+Z\",\"right\":\"+X\"},\"units\":\"studs at garden size\",\"nativeScaleFactor\":1.3888888888888888,\"palette\":{\"body\":\"#E5DBD0\",\"secondary\":\"#C595A0\",\"face\":\"#443641\",\"mouth\":\"#855763\",\"ivory\":\"#FFF6E9\",\"blush\":\"#D9A6A2\"},\"anchors\":{\"Root\":[0,0,0],\"Head\":[0,0.89,0],\"Body\":[0,0.445,0],\"HandL\":[-0.354,0.575,0.09],\"HandR\":[0.354,0.575,0.09],\"FootL\":[-0.24,0.112,0.035],\"FootR\":[0.24,0.112,0.035],\"EyeLine\":[0,0.987,0.44],\"HandCatch\":[0,0.54,0.43],\"CharmAnchor\":[0,1.752,0.005]},\"pieces\":[{\"name\":\"Body\",\"channel\":\"Body\",\"shape\":\"ellipsoid\",\"center\":[0,0.442,0.0],\"size\":[0.837,0.83,0.733],\"xyzEulerDeg\":[0,0,0],\"colorRole\":\"body\"},{\"name\":\"Head\",\"channel\":\"Head\",\"shape\":\"ellipsoid\",\"center\":[0,1.045,0.016],\"size\":[1.31,0.897,0.928],\"xyzEulerDeg\":[0,0,0],\"colorRole\":\"body\"},{\"name\":\"CrownL\",\"channel\":\"Head\",\"shape\":\"ellipsoid\",\"center\":[-0.26,1.386,-0.039],\"size\":[0.313,0.277,0.303],\"xyzEulerDeg\":[0,0,-10],\"colorRole\":\"body\"},{\"name\":\"CrownR\",\"channel\":\"Head\",\"shape\":\"ellipsoid\",\"center\":[0.264,1.373,-0.063],\"size\":[0.258,0.236,0.282],\"xyzEulerDeg\":[0,0,10],\"colorRole\":\"body\"},{\"name\":\"FootL\",\"channel\":\"FootL\",\"shape\":\"ellipsoid\",\"center\":[-0.24,0.12,0.08],\"size\":[0.34,0.24,0.389],\"xyzEulerDeg\":[0,0,0],\"colorRole\":\"secondary\"},{\"name\":\"Ha