:\"ellipsoid\",\"center\":[0.333,0.552,0.146],\"size\":[0.196,0.301,0.232],\"xyzEulerDeg\":[0,0,-17],\"colorRole\":\"body\"},{\"name\":\"CuffTrimR\",\"channel\":\"CuffR\",\"shape\":\"ellipsoid\",\"center\":[0.357,0.454,0.182],\"size\":[0.114,0.079,0.133],\"xyzEulerDeg\":[0,0,-17],\"colorRole\":\"secondary\"},{\"name\":\"EyeR\",\"channel\":\"Head\",\"shape\":\"ellipsoid\",\"center\":[0.265,1.011,0.411],\"size\":[0.164,0.195,0.044],\"xyzEulerDeg\":[0,17,0],\"colorRole\":\"face\"},{\"name\":\"GlintR\",\"channel\":\"Head\",\"shape\":\"ellipsoid\",\"center\":[0.24200000000000002,1.05,0.434],\"size\":[0.049,0.047,0.013],\"xyzEulerDeg\":[0,0,0],\"colorRole\":\"ivory\"},{\"name\":\"CheekR\",\"channel\":\"Head\",\"shape\":\"ellipsoid\",\"center\":[0.428,0.942,0.37],\"size\":[0.144,0.071,0.03],\"xyzEulerDeg\":[0,20,0],\"colorRole\":\"blush\"},{\"name\":\"MouthSmile\",\"channel\":\"Head\",\"shape\":\"smile\",\"center\":[0,0.926,0.439],\"size\":[0.18,0.058,0.024],\"xyzEulerDeg\":[0,0,0],\"colorRole\":\"mouth\"},{\"name\":\"MouthO\",\"channel\":\"Head\",\"shape\":\"ellipsoid\",\"center\":[0,0.932,0.456],\"size\":[0.101,0.112,0.042],\"xyzEulerDeg\":[0,0,0],\"colorRole\":\"mouth\"},{\"name\":\"CharmDot\",\"channel\":\"Charm\",\"shape\":\"ellipsoid\",\"center\":[0,1.739,0],\"size\":[0.22,0.22,0.22],\"xyzEulerDeg\":[0,0,0],\"colorRole\":\"secondary\"}]}}]=])\nreturn definitions\n","client/PetFace":"-- Face identity remains shaded independently of grouped pigment surface fills.\nlocal Clock=require(script.Parent.HollowClock)\nlocal Night=require(script.Parent.PetNightSurfaces)\nlocal Face={}\nfunction Face.daylight()return Clock.lastDaylight or 1 end\nfunction Face.paint(entry,worldContext,color,daylight)\n local role=entry.faceRole;if not role then return end\n local base=color or entry.faceBaseColor\n local glint=worldContext==true and daylight<.35 and role==\"spark\"\n local tint=if glint then Color3.new(base.R*.30,base.G*.30,base.B*.30)else base\n local material=if glint then Enum.Material.Neon else entry.faceBaseMaterial\n if entry.faceColor~=tint then entry.part.Color=tint;entry.faceColor=tint end\n if entry.faceMaterial~=material then entry.part.Material=material;entry.faceMaterial=material end\nend\nfunction Face.paintSurface(entry,visual,daylight)Night.paint(entry,visual,daylight)end\nreturn Face\n","client/PetNightSurfaces":"-- Two grouped occluded fills retain the shaded material under each saved channel.\n-- No per-part Highlights, lights, geometry clones, exposure or palette mutation.\nlocal Palette=require(game:GetService(\"ReplicatedStorage\")._RigStudyArchive_bb8c60b.Shared.PetPalette)\nlocal Night={DefaultTreatment=\"tonalRoleFill\"}\nlocal function prepare(visual)\n local groups={}\n for _,role in ipairs({\"body\",\"secondary\"})do\n  local model=Instance.new(\"Model\");model.Name=if role==\"body\"then \"MainSurfaces\"else \"SecondarySurfaces\";model.Parent=visual.model\n  local fill=Instance.new(\"Highlight\");fill.Name=\"Night\"..model.Name;fill.Adornee=model;fill.DepthMode=Enum.HighlightDepthMode.Occluded;fill.OutlineTransparency=1;fill.FillTransparency=1;fill.Enabled=false;fill.Parent=visual.model\n  groups[role]={model=model,fill=fill}\n end\n for _,entry in ipairs(visual.pieces)do\n  if entry.nightHeadLift then entry.nightHeadLift:Destroy();entry.nightHeadLift=nil end\n  local group=groups[entry.colorRole]\n  if group then entry.part.Parent=group.model end\n end\n visual.nightGroups=groups;return groups\nend\nfunction Night.paint(entry,visual,daylight)\n if entry.colorRole~=\"body\"and entry.colorRole~=\"secondary\"then return end\n local base=entry.color or entry.originalColor or entry.part.Color\n local treatment=if visual.nightTreatment==\"groupedRoleFill\"then \"groupedRoleFill\"else Night.DefaultTreatment\n local dusk=math.clamp((.50-daylight)/.50,0,1);dusk=dusk*dusk*(3-2*dusk)\n local tone=1\n if visual.worldContext and treatment==\"tonalRoleFill\"and visual.definition then\n  if entry.name==\"Body\"then tone=1-.26*dusk\n  elseif entry.name==\"HandL\"or entry.name==\"HandR\"then tone=1-.12*dusk end\n end\n local rendered=if tone<1 then Palette.tint(base,Color3.new(0,0,0),1-tone)else base\n local material=entry.faceBaseMaterial or Enum.Material.SmoothPlastic\n if entry.part.Color~=rendered then entry.part.Color=rendered end\n if entry.part.Material~=material then entry.part.Material=material end\n if not visual.worldContext then return end\n local groups=visual.nightGroups or prepare(visual)\n local colors=visual.colors or {};local charm=visual.charmVisible~=false\n if visual.nightDaylight==daylight and visual.nightColors==colors and visual.nightCharm==charm and visual.nightStyle==treatment then return end\n visual.nightDaylight,visual.nightColors,visual.nightCharm,visual.nightStyle=daylight,colors,charm,treatment\n local active=if visual.nightFillActive then daylight<.48 else daylight<.44\n visual.nightFillActive=active\n for role,group in pairs(groups)do\n  local color=colors[role]or base\n  local opacity=if treatment==\"groupedRoleFill\"then (if role==\"body\"then .55 else .42)else (if role==\"body\"then .32 else .36)\n  group.fill.FillColor=color;group.fill.FillTransparency=1-opacity*dusk;group.fill.Enabled=active and dusk>.001\n end\n for _,piece in ipairs(visual.pieces)do if piece.role==\"charm\"then\n  local parent=if charm then groups.secondary.model else visual.model\n  if piece.part.Parent~=parent then piece.part.Parent=parent end\n end end\nend\nreturn Night\n","client/PetCharms":"-- A confirmed secondary-colored Dot. Hidden dots never enter any hit hull.\nlocal Charms={}\nfunction Charms.apply(visual,appearance)\n visual.charmVisible=type(appearance)~=\"table\"or appearance.charmVisible~=false\n visual.model:SetAttribute(\"CharmVisible\",visual.charmVisible)\n for _,entry in ipairs(visual.pieces)do if entry.role==\"charm\"then entry.part.Transparency=if visual.charmVisible then 0 else 1 end end\nend\nfunction Charms.isVisible(visual,entry)return entry.role~=\"charm\"or visual.charmVisible~=false end\nfunction Charms.pose(visual,frame,size,x,y,stretch)\n -- Separate movement from the head, retaining its authored attachment orientation.\n -- Volume stays constant as the Dot softly squashes at the turn of its bob.\n local width=1/math.sqrt(stretch)\n return frame*CFrame.new(x*(visual.scale or 1),y*(visual.scale or 1),0),\n  Vector3.new(size.X*width,size.Y*stretch,size.Z*width)\nend\nreturn Charms\n","client/PetPoseSampler":"-- Cached expressive poses, fresh root/heading and planted feet every rendered frame.\n-- One host render clock; cadence can be 12/15 or 0 for the comparison control.\nlocal Bounds=require(script.Parent.PetRigBounds)\nlocal Sampler={DefaultCadence=15}\nlocal tau=math.pi*2\nlocal function footSide(entry)\n local channel=entry.channel\n if channel==\"FootL\"or entry.role==\"footLeft\"or entry.foot==\"footLeft\"then return -1 end\n if channel==\"FootR\"or entry.role==\"footRight\"or entry.foot==\"footRight\"then return 1 end\n return nil\nend\nlocal function rootOf(v)return CFrame.new(v.origin)*CFrame.Angles(0,v.yaw or 0,0)end\nfunction Sampler.attach(visual)\n if visual.sampledPose then return visual end;visual.sampledPose=true;visual.poseCadence=Sampler.DefaultCadence\n local original=visual.update;local greet=visual.greet\n function visual:greet()self.poseDirty=true;return greet(self)end\n local function plant(self,slot,frame,root)\n  local side=slot.side;if not side or not self.worldContext then return frame end\n  local weight=self.gaitWeight or 0;local focus=self.focusPose or self.gardenFocus or self.gardenAction==\"focus\"\n  local scale=self.worldScale or 1\n  if focus or self.gardenAction==\"greet\"or self.gardenAction==\"shove\"then slot.anchor=nil;slot.stance=nil;slot.walking=false;return frame end\n  local rest=slot.rest;local base=root*rest\n  if self.gardenPivot then\n   slot.walking=false\n   local phase=math.clamp(self.gardenPivotPhase or 0,0,1);local turn=self.gardenPivotTurn or 0\n   local halfTurn=math.abs(turn)>math.pi*.65;local beats=if halfTurn then 2 else 1\n   local beat=math.min(beats-1,math.floor(phase*beats));local u=math.clamp(phase*beats-beat,0,1)\n   local initialSupport=if turn>=0 then -1 else 1;local support=if beat%2==0 then initialSupport else -initialSupport\n   local smooth=phase*phase*(3-2*phase)\n   if not self.pivotStartYaw then self.pivotStartYaw=(self.yaw or 0)-turn*smooth end\n   if slot.pivotBeat~=beat then\n    slot.pivotBeat=beat;slot.pivotFrom=slot.lastPlaced or frame.Position\n    slot.pivotSupport=slot.pivotFrom;slot.pivotYawFrom=self.yaw or 0\n   end\n   local endYaw=self.pivotStartYaw+turn*(beat+1)/beats\n   local target=(CFrame.new(self.origin)*CFrame.Angles(0,endYaw,0)*rest).Position\n   local position\n   if side==support then position=slot.pivotSupport\n   else\n    local ease=u*u*(3-2*u)\n    position=slot.pivotFrom:Lerp(target,ease)+Vector3.new(0,math.sin(math.pi*u)*(if self.reducedEffects then .035 else .14)*scale,0)\n   end\n   local half=slot.entry.part.Size.Y*.5;position=Vector3.new(position.X,math.max(self.origin.Y+half,position.Y),position.Z)\n   slot.lastPlaced=position;slot.anchor=position;slot.lastPlant=position;slot.stance=side==support\n   local footYaw=if side==support then slot.pivotYawFrom else slot.pivotYawFrom+(endYaw-slot.pivotYawFrom)*(u*u*(3-2*u))\n   return CFrame.new(position)*CFrame.Angles(0,footYaw,0)*rest.Rotation\n  elseif slot.pivotBeat then slot.pivotBeat=nil;slot.pivotFrom=nil;slot.pivotSupport=nil;slot.stance=nil end\n  local heading=Vector3.new(math.sin(self.yaw or 0),0,math.cos(self.yaw or 0))\n  local walking=weight>=.035\n  if walking and not slot.walking then slot.stance=nil;slot.anchor=nil end\n  slot.walking=walking\n  local phase=((self.gaitPhase or 0)/tau+(if side<0 then 0 else .5))%1\n  local stance=phase<.58 or weight<.035\n  if stance then\n   if not slot.stance or not slot.anchor then\n    local ahead=if weight>.035 then .26*scale else 0\n    slot.anchor=base.Position+heading*ahead;slot.anchorYaw=self.yaw or 0\n   end\n   local gap=Vector3.new(slot.anchor.X-base.X,0,slot.anchor.Z-base.Z)\n   if gap.Magnitude>.72*scale then\n    -- A discontinuity or teleported owner releases the old stance explicitly.\n    slot.anchor=base.Position;slot.anchorYaw=self.yaw or 0\n   end\n   slot.stance=true\n   local half=slot.entry.part.Size.Y*.5\n   local y=math.max(self.origin.Y+half,slot.anchor.Y)\n   local cf=CFrame.new(slot.anchor.X,y,slot.anchor.Z)*CFrame.Angles(0,slot.anchorYaw,0)*rest.Rotation\n   slot.lastPlant=cf.Position;slot.lastPlaced=cf.Position;return cf\n  end\n  if slot.stance then slot.swingFrom=slot.lastPlant or frame.Position;slot.stance=false end\n  local u=math.clamp((phase-.58)/.42,0,1);local smooth=u*u*(3-2*u)\n  local target=base.Position+heading*.26*scale\n  local start=slot.swingFrom or(base.Position-heading*.45*scale)\n  local position=start:Lerp(target,smooth)+Vector3.new(0,math.sin(math.pi*u)*(if self.reducedEffects then .035 else .15)*scale,0)\n  local half=slot.entry.part.Size.Y*.5;position=Vector3.new(position.X,math.max(self.origin.Y+half,position.Y),position.Z)\n  slot.lastPlaced=position;return CFrame.new(position)*root.Rotation*rest.Rotation\n end\n function visual:update(dt)\n  dt=if type(dt)==\"number\"and dt==dt and dt>=0 and dt<math.huge then dt else 0\n  self.poseElapsed=(self.poseElapsed or 0)+dt;self.poseClock=(self.poseClock or 0)+dt\n  local cadence=self.poseCadence or Sampler.DefaultCadence;local bucket=if cadence>0 then math.floor((self.cosmeticTime or self.poseClock)*cadence+1e-6)else -1\n  local stateKey=tostring(self.reducedEffects)..\":\"..tostring(self.focusPose)..\":\"..tostring(self.expression)..\":\"..tostring(self.gardenAction)..\":\"..tostring(self.charmVisible)..\":\"..tostring(self.petting)\n  local root=rootOf(self)\n  if not self.gardenPivot then self.pivotStartYaw=nil end\n  if not self.poseSlots or cadence<=0 or self.poseDirty or bucket~=self.poseBucket or stateKey~=self.poseStateKey then\n   original(self,self.poseElapsed);self.poseElapsed=0;self.poseBucket=bucket;self.poseStateKey=stateKey;self.poseDirty=false\n   local slots=self.poseSlots or {};self.poseSlots=slots\n   for i,entry in ipairs(self.pieces)do\n    local slot=slots[i]or{entry=entry,side=footSide(entry)};slots[i]=slot\n    slot.localFrame=root:ToObjectSpace(entry.part.CFrame)\n    if slot.side and not slot.rest then\n     local frame=entry.frame or entry.offset;local scale=self.scale or self.worldScale or 1\n     slot.rest=CFrame.new(frame.Position*(if self.scale then 1 else scale))*frame.Rotation\n    end\n   end\n   self.model:SetAttribute(\"PoseCadence\",cadence)\n   self.poseSamples=(self.poseSamples or 0)+1\n  end\n  Bounds.begin(self);self.bodyHull=self.bodyHull or {};Bounds.begin(self.bodyHull)\n  for _,slot in ipairs(self.poseSlots)do\n   local entry=slot.entry;local part=entry.part;local frame=root*slot.localFrame\n   frame=plant(self,slot,frame,root);part.CFrame=frame\n   if part.Transparency<1 then Bounds.include(self,frame,part.Size);if entry.role~=\"charm\"then Bounds.include(self.bodyHull,frame,part.Size)end end\n  end\n  Bounds.finish(self);Bounds.finish(self.bodyHull);self.bodyBoundsFrame,self.bodyBoundsSize=self.bodyHull.rigBoundsFrame,self.bodyHull.rigBoundsSize\n end\n visual.poseDirty=true;visual:update(0);return visual\nend\nreturn Sampler\n","client/PetRigBounds":"-- Puddle's floor ripple is visual FX, not part of its subject silhouette.\n-- Only its world renderer accumulates this cache in the existing pose loop.\nlocal Bounds={}\nfunction Bounds.begin(visual)\n visual.rigMinX,visual.rigMinY,visual.rigMinZ=math.huge,math.huge,math.huge\n visual.rigMaxX,visual.rigMaxY,visual.rigMaxZ=-math.huge,-math.huge,-math.huge\nend\nfunction Bounds.include(visual,cf,size)\n local r,u,l=cf.RightVector,cf.UpVector,cf.LookVector\n local x=(math.abs(r.X)*size.X+math.abs(u.X)*size.Y+math.abs(l.X)*size.Z)*.5\n local y=(math.abs(r.Y)*size.X+math.abs(u.Y)*size.Y+math.abs(l.Y)*size.Z)*.5\n local z=(math.abs(r.Z)*size.X+math.abs(u.Z)*size.Y+math.abs(l.Z)*size.Z)*.5\n visual.rigMinX,visual.rigMinY,visual.rigMinZ=math.min(visual.rigMinX,cf.X-x),math.min(visual.rigMinY,cf.Y-y),math.min(visual.rigMinZ,cf.Z-z)\n visual.rigMaxX,visual.rigMaxY,visual.rigMaxZ=math.max(visual.rigMaxX,cf.X+x),math.max(visual.rigMaxY,cf.Y+y),math.max(visual.rigMaxZ,cf.Z+z)\nend\nfunction Bounds.finish(visual)\n visual.rigBoundsFrame=CFrame.new((visual.rigMinX+visual.rigMaxX)*.5,(visual.rigMinY+visual.rigMaxY)*.5,(visual.rigMinZ+visual.rigMaxZ)*.5)\n visual.rigBoundsSize=Vector3.new(visual.rigMaxX-visual.rigMinX,visual.rigMaxY-visual.rigMinY,visual.rigMaxZ-visual.rigMinZ)\nend\nfunction Bounds.get(visual)\n if visual.rigBoundsFrame and visual.rigBoundsSize then return visual.rigBoundsFrame,visual.rigBoundsSize end\n return visual.model:GetBoundingBox()\nend\nfunction Bounds.getBody(visual)\n if visual.bodyBoundsFrame and visual.bodyBoundsSize then return visual.bodyBoundsFrame,visual.bodyBoundsSize end\n return Bounds.get(visual)\nend\nreturn Bounds\n","client/BonusPetVisual":"local Face=require(script.Parent.PetFace)\nlocal Visual = {}\nVisual.__index = Visual\nlocal GREET_TIME = 0.86\nlocal flameHinge = CFrame.new(0, 1.8, 0)\n\nlocal function piece(self, name, size, offset, color, ball, animated)\n\tlocal part = Instance.new(\"Part\")\n\tpart.Name = name\n\tpart.Size = size*self.worldScale\n\tpart.Anchored = true\n\tpart.CanCollide = false\n\tpart.CanTouch = false\n\tpart.CanQuery = name == \"Body\"\n\tpart.Color = color\n\tpart.Material = Enum.Material.SmoothPlastic\n\tif ball then\n\t\tlocal mesh = Instance.new(\"SpecialMesh\")\n\t\tmesh.MeshType = Enum.MeshType.Sphere\n\t\tmesh.Parent = part\n\tend\n\tpart.Parent = self.model\n\ttable.insert(self.pieces, { part = part, size=size, offset = offset, animated = animated==true, foot = if type(animated)==\"string\"then animated else nil,faceRole=if name==\"Cheek\"then \"cheek\"elseif name==\"EyeSpark\"then \"spark\"else nil,face