tor3.new(0.23, 0.34, 0.09),\n\t\t\tCFrame.new(side * 0.35, 1.66, 0.745), COLORS.ink, false, \"eye\")\n\t\tpiece(self, \"EyeSpark\", Vector3.new(0.065, 0.075, 0.035),\n\t\t\tCFrame.new(side * 0.35 - 0.035, 1.74, 0.80), COLORS.shell, false, \"spark\")\n\t\tpiece(self, \"Cheek\", Vector3.new(0.22, 0.12, 0.055),\n\t\t\tCFrame.new(side * 0.58, 1.43, 0.655), COLORS.peach, false)\n\tend\n\tpiece(self, \"Smile\", Vector3.new(0.18, 0.065, 0.055),\n\t\tCFrame.new(0, 1.37, 0.79), COLORS.ink, false)\n\tfor _, side in ipairs({ -1, 1 }) do\n\t\tpiece(self, \"SmileCorner\", Vector3.new(0.055, 0.09, 0.055),\n\t\t\tCFrame.new(side * 0.10, 1.405, 0.79), COLORS.ink, false)\n\tend\n\t-- The sprig leans left. Two broad leaf lobes read even without color.\n\tlocal crown = CFrame.new(-0.03, 2.36, 0) * CFrame.Angles(0, 0, math.rad(24))\n\tpiece(self, \"SprigStem\", Vector3.new(0.14, 0.65, 0.16),\n\t\tcrown * CFrame.new(0, 0.26, 0), COLORS.leafDark, false, \"sprig\")\n\tpiece(self, \"WideLeaf\", Vector3.new(0.72, 0.25, 0.40),\n\t\tcrown * CFrame.new(-0.26, 0.49, 0) * CFrame.Angles(0, 0, -0.30),\n\t\tCOLORS.green, true, \"sprig\")\n\tpiece(self, \"NewLeaf\", Vector3.new(0.53, 0.22, 0.33),\n\t\tcrown * CFrame.new(0.22, 0.59, 0) * CFrame.Angles(0, 0, 0.58),\n\t\tCOLORS.leafLight, true, \"sprig\")\n\tpiece(self, \"LeafPixel\", Vector3.new(0.22, 0.055, 0.16),\n\t\tcrown * CFrame.new(-0.26, 0.60, 0.09) * CFrame.Angles(0, 0, -0.30),\n\t\tCOLORS.leafLight, false, \"sprig\")\n\tif isBloom then\n\t\tlocal bloom = crown * CFrame.new(0.03, 0.86, 0.09)\n\t\tfor index = 0, 4 do\n\t\t\tlocal angle = index * math.pi * 2 / 5\n\t\t\tpiece(self, \"Petal\", Vector3.new(0.28, 0.40, 0.18),\n\t\t\t\tbloom * CFrame.Angles(0, 0, angle) * CFrame.new(0, 0.20, 0), bodyColor, true, \"sprig\")\n\t\tend\n\t\tpiece(self, \"Pollen\", Vector3.new(0.22, 0.22, 0.18),\n\t\t\tbloom * CFrame.new(0, 0, 0.10), COLORS.cream, true, \"sprig\")\n\tend\n\tmodel.Parent = parent\n\tself:update(0)\n\treturn self\nend\n\nfunction PipVisual:greet()\n\tself.greeting = 0\n\tself.lastFrame = -1\n\tself:update(0)\nend\n\nfunction PipVisual:update(dt)\n\tif not self.model.Parent then\n\t\treturn\n\tend\n\tif dt ~= dt or dt == math.huge or dt < 0 then\n\t\tdt = 0\n\tend\n\tself.time += dt\n\tself.affection=math.max(0,(self.affection or 0)-dt)\n\tlocal happy=self.petting==true or self.affection>0\n local faceDaylight=Face.daylight()\n\tself.greeting += dt\n\t-- Position, heading and pose update every render frame while following.\n\tlocal t = self.time\n\tlocal g = self.greeting\n\tlocal bounce, squash, wave = 0, 0, 0\n\tif g < 0.18 then\n\t\tsquash = 0.12 * math.sin(g / 0.18 * math.pi / 2)\n\telseif g < 0.76 then\n\t\tlocal u = (g - 0.18) / 0.58\n\t\tbounce = 0.56 * math.sin(u * math.pi)\n\t\tsquash = -0.10 * math.sin(u * math.pi)\n\t\twave = math.sin(u * math.pi) * 0.85\n\telseif g < 1.25 then\n\t\tlocal u = (g - 0.76) / 0.49\n\t\tsquash = 0.12 * math.sin(u * math.pi) * (1 - u)\n\tend\n\tlocal reduced=self.reducedEffects==true\n\tif reduced then bounce,squash,wave=0,0,0 end\n\tif self.focusPose then bounce*=.35 end\n\tlocal gait=self.gaitWeight or 0;local stride=self.gaitPhase or 0\n\tlocal breathe = if reduced then 0 else math.sin(t * 2.2) * 0.012\n\tlocal worldScale=self.worldScale\n local travelBob=if self.worldContext and not reduced then self.movementBob or 0 else 0\n\tlocal scale = Vector3.new(1 + squash * 0.48 - breathe, 1 - squash + breathe, 1 + squash * 0.30)\n\tlocal root = CFrame.new(self.origin + Vector3.new(0, (bounce+travelBob)*worldScale, 0))\n\t\t* CFrame.Angles(0, (self.yaw or 0) + (if reduced then 0 else math.sin(t * 1.1) * 0.035), if reduced then 0 else math.sin(t * 1.8) * 0.025+(self.affectionTilt or 0))\n\tlocal blink = (t % 4.8 > 4.62) or (g > 0.30 and g < 0.61) or happy\n\tfor _, entry in ipairs(self.pieces) do\n\t\tlocal rest = entry.frame\n\t\tlocal pose = CFrame.new(rest.Position * scale) * rest.Rotation\n\t\tlocal size = entry.size * scale\n\t\tif entry.role==\"footLeft\"or entry.role==\"footRight\"then\n\t\t\tlocal step=math.sin(stride+(if entry.role==\"footLeft\"then 0 else math.pi))\n\t\t\tpose=CFrame.new(0,math.max(0,step)*.085*gait-travelBob,step*.075*gait)*pose\n\t\telseif entry.role == \"wave\" then\n\t\t\tpose *= CFrame.Angles(0, 0, -wave)\n\t\telseif entry.role == \"sprig\" then\n\t\t\t-- Rotation around its base prevents the sprig from sliding off the head.\n\t\t\tlocal base = CFrame.new(Vector3.new(0, 2.36, 0) * scale)\n\t\t\tpose = base * CFrame.Angles(0, 0, (if reduced then 0 else math.sin(t * 2.5) * 0.045) + wave * 0.12)\n\t\t\t\t* base:Inverse() * pose\n\t\telseif entry.role == \"eye\" and blink then\n\t\t\tsize = Vector3.new(size.X, 0.065, size.Z)\n\t\tend\n\t\tif happy and entry.part.Name==\"Smile\"then size=Vector3.new(size.X*1.5,size.Y*.8,size.Z)elseif happy and entry.part.Name==\"SmileCorner\"then pose=CFrame.new(0,.04,0)*pose end\n\t\tFace.paint(entry,self.worldContext,if entry.faceRole==\"cheek\"then COLORS.peach:Lerp(Color3.fromHex(\"#F39BAF\"),self.affectionBlush or 0)else nil,faceDaylight)\n\t\tentry.part.Transparency = if entry.role == \"spark\" and blink then 1 else 0\n\t\tentry.part.Size = size*worldScale\n\t\tlocal placed=root * (CFrame.new(pose.Position*worldScale)*pose.Rotation)\n\t\tif self.worldContext and(entry.role==\"footLeft\"or entry.role==\"footRight\")then\n\t\t\tlocal half=(math.abs(placed.RightVector.Y)*entry.part.Size.X+math.abs(placed.UpVector.Y)*entry.part.Size.Y+math.abs(placed.LookVector.Y)*entry.part.Size.Z)*.5\n\t\t\tplaced+=Vector3.new(0,math.max(0,self.origin.Y-(placed.Y-half)),0)\n\t\tend\n\t\tentry.part.CFrame=placed\n\tend\nend\n\nfunction PipVisual:destroy()\n\tself.model:Destroy()\nend\n\nreturn PipVisual\n","client/GardenPetVisual":"-- Astra-authored babies. One host-owned update; geometry is created only once.\nlocal ReplicatedStorage=game:GetService(\"ReplicatedStorage\")\nlocal Definitions=require(ReplicatedStorage._RigStudyArchive_bb8c60b.Shared.PetRigDefinitions)\nlocal Bounds=require(script.Parent.PetRigBounds)\nlocal Expression=require(script.Parent.PetExpression)\nlocal Charms=require(script.Parent.PetCharms)\nlocal Face=require(script.Parent.PetFace)\nlocal Motion=require(script.Parent.PetIdleMotion)\nlocal Palette=require(ReplicatedStorage._RigStudyArchive_bb8c60b.Shared.PetPalette)\nlocal Visual={};Visual.__index=Visual\nlocal function v(a)return Vector3.new(a[1],a[2],a[3])end\nlocal function authoredFrame(def,scale)\n local a=def.xyzEulerDeg\n return CFrame.new(v(def.center)*scale)*CFrame.Angles(math.rad(a[1]),math.rad(a[2]),math.rad(a[3]))\nend\nlocal function configure(part,color)\n part.Anchored=true;part.CanCollide=false;part.CanTouch=false;part.CanQuery=false;part.CastShadow=true\n part.Material=Enum.Material.SmoothPlastic;part.Color=color\nend\nlocal function add(self,part,def,frame,size)\n configure(part,self.colors[def.colorRole])\n if string.find(def.name,\"Cheek\")then part.Color=Color3.fromHex(self.definition.palette.body):Lerp(self.colors.blush,.82)end\n part.Name=def.name;part.Size=size;part.Parent=self.model\n local role=if def.channel==\"Charm\"then \"charm\"else nil\n local entry={part=part,name=def.name,colorRole=def.colorRole,channel=def.channel,frame=frame,size=size,role=role,color=part.Color,faceRole=if string.find(def.name,\"Cheek\")then \"cheek\"elseif string.find(def.name,\"Glint\")then \"spark\"else nil,faceBaseColor=part.Color,faceBaseMaterial=part.Material}\n table.insert(self.pieces,entry)\n if def.name==\"Body\"then self.model.PrimaryPart=part;part.CanQuery=true end\n return entry\nend\nlocal function ellipsoid()\n local part=Instance.new(\"Part\");local mesh=Instance.new(\"SpecialMesh\");mesh.MeshType=Enum.MeshType.Sphere;mesh.Parent=part;return part\nend\nlocal function native(self)\n for _,def in ipairs(self.definition.pieces)do\n  local cf,size=authoredFrame(def,self.scale),v(def.size)*self.scale\n  if def.shape==\"tooth\"then\n   -- Two wedges form one downward pointed tooth, with a real six-tip grin.\n   for _,side in ipairs({-1,1})do\n    local part=Instance.new(\"WedgePart\")\n    add(self,part,def,cf*CFrame.new(side*size.X*.25,0,0)*CFrame.Angles(0,side*math.pi*.5,math.pi),Vector3.new(size.Z,size.Y,size.X*.5))\n   end\n  elseif def.shape==\"smile\"and self.definition.id==\"ovelle\"then\n   for i=-1,1 do\n    local part=ellipsoid()\n    add(self,part,def,cf*CFrame.new(i*size.X*.28,math.abs(i)*size.Y*.18,0)*CFrame.Angles(0,0,i*.28),Vector3.new(size.X*.48,size.Y*.48,size.Z))\n   end\n  else\n   local part=ellipsoid()\n   add(self,part,def,cf,size)\n  end\n end\n self.backend=\"NativeRecipe\"\nend\nlocal function imported(self)\n local assets=ReplicatedStorage:FindFirstChild(\"PetAssets\")\n local source=assets and assets:FindFirstChild(if self.definition.id==\"zivvi\"then \"Zivvi\"else \"Ovelle\")\n if not source or not source:IsA(\"Model\")then return false end\n -- Templates are trusted authored assets. Their pivot is at the paws, import front -Z.\n local marker=source:FindFirstChild(\"PawsOrigin\")\n local sourcePivot=if marker and marker:IsA(\"CFrameValue\")then marker.Value else source:GetPivot();local lookup={}\n for _,def in ipairs(self.definition.pieces)do lookup[def.name]=def end\n local pending={};local present={}\n for _,part in ipairs(source:GetDescendants())do if part:IsA(\"BasePart\")then\n  local name=string.gsub(part.Name,\"^.-__\",\"\")\n  local def=lookup[name]\n  if not def and string.find(name,\"^CuffTrim\")then def={name=name,channel=(if self.definition.id==\"zivvi\"then \"Hand\"else \"Cuff\")..string.sub(name,-1),colorRole=\"secondary\"}end\n  if not def and name==\"Teeth\"then def={name=name,channel=\"Face\",colorRole=\"ivory\"}end\n  if not def and name==\"Mouth\"then def=lookup.MouthSmile end\n  if not def and name==\"Cheeks\"then def={name=name,channel=\"Face\",colorRole=\"blush\"}end\n  if def then\n   -- Rojo can create named MeshParts without their immutable mesh resource.\n   -- Never mistake checkerboard placeholders for the authored asset backend.\n   if not part:IsA(\"MeshPart\")or part.MeshId==\"\"or part.MeshSize.X<=0 or part.MeshSize.Y<=0 or part.MeshSize.Z<=0 then return false end\n   table.insert(pending,{part=part,def=def});present[def.name]=true\n  end\n end end\n for _,name in ipairs({\"Body\",\"Head\",\"HandL\",\"HandR\",\"FootL\",\"FootR\",\"EyeL\",\"EyeR\",\"MouthSmile\",\"CharmDot\"})do if not present[name]then return false end end\n if self.definition.id==\"zivvi\"and not present.Teeth then return false end\n local rotation=CFrame.Angles(0,math.pi,0)\n for _,item in ipairs(pending)do\n  local localCF=rotation*sourcePivot:ToObjectSpace(item.part.CFrame)\n  add(self,item.part:Clone(),item.def,CFrame.new(localCF.Position*self.scale)*localCF.Rotation,item.part.Size*self.scale)\n end\n -- O mouth remains a separate shape so surprise reads even without a blendshape.\n if not self.model:FindFirstChild(\"MouthO\")then\n  local def=lookup.MouthO;local part=ellipsoid()\n  add(self,part,def,authoredFrame(def,self.scale),v(def.size)*self.scale)\n end\n self.backend=\"AuthoredMesh\";return self.model.PrimaryPart~=nil\nend\nfunction Visual.new(parent,origin,pet,worldScale,appearance,options)\n local definition=assert(Definitions[pet.id],\"No authored garden rig for alias\")\n local model=Instance.new(\"Model\");model.Name=pet.name\n local cachedColors=Palette.resolve(pet.id,appearance)\n local self=setmetatable({petId=pet.id,nightTreatment=options and options.nightTreatment or \"shadedHead\",secondaryColor=cachedColors.secondary,colors=cachedColors,model=model,definition=definition,pieces={},bodyHull={},origin=origin,yaw=0,time=0,greeting=2,worldScale=worldScale or 1,worldContext=worldScale~=nil,scale=(worldScale or 1)*definition.nativeScaleFactor,expression=\"neutral\",lastActionId=nil},Visual)\n if(options and options.native==true)or not imported(self)then for _,entry in ipairs(self.pieces)do entry.part:Destroy()end;table.clear(self.pieces);native(self)end\n model:SetAttribute(\"PetFamily\",pet.id);model:SetAttribute(\"RigId\",definition.id);model:SetAttribute(\"RigBackend\",self.backend)\n model.Parent=parent;self:applyAppearance(appearance);return self\nend\nfunction Visual:greet()self.greeting=0 end\nfunction Visual:applyAppearance(appearance)\n local colors=Palette.resolve(self.petId,appearance)\n self.colors,self.secondaryColor=colors,colors.secondary\n for _,entry in ipairs(self.pieces)do\n  if entry.colorRole==\"body\"or entry.colorRole==\"secondary\"then\n   local color=colors[entry.colorRole]\n   if entry.part.Color~=color then entry.part.Color=color end\n   entry.color=color\n  end\n end\n self.model:SetAttribute(\"HueBody\",appearance and appearance.body or \"original\")\n self.model:SetAttribute(\"HueRank\",appearance and appearance.bodyRank or 0)\n self.model:SetAttribute(\"HueSecondary\",appearance and appearance.secondary or \"default\")\n Charms.apply(self,appearance);self.poseDirty=true;self:update(0)\nend\nfunction Visual:applyGardenPose(sample)\n self.gardenAction,self.actionPhase,self.expression=sample.action,sample.actionPhase or sample.phase or 0,sample.expression or \"neutral\"\n self.gardenFocus=sample.action==\"focus\"\n if sample.action==\"greet\"and(sample.actionId~=self.lastActionId or sample.generation~=self.lastGeneration)then self:greet()end\n self.lastActionId,self.lastGeneration=sample.actionId,sample.generation\nend\nfunction Visual:update(dt)\n self.time+=dt;self.greeting=math.min(2,self.greeting+dt)\n local expression=Expression.name(self);local pose=Expression.get(expression);local reduced=self.reducedEffects==true\n local blink,breath,bodyStretch,headPitch,headYaw,dotX,dotY,dotStretch=Motion.sample(self,expression)\n local wave=if reduced then 0 else math.sin(math.clamp(self.greeting/1.2,0,1)*math.pi)\n if self.greeting>=1.2 then wave=0 end\n local greet=wave*(if self.focusPose then .35 else 1)\n local gait=if reduced then 0 else(self.gaitWeight or 0)\n local step=math.sin(self.gaitPhase or 0)*gait\n local shove=if self.gardenAction==\"shove\"then math.sin(math.clamp(self.actionPhase or 0,0,1)*math.pi*4)else 0\n local daylight=Face.daylight()\n local root=CFrame.new(self.origin)*CFrame.Angles(0,self.yaw or 0,0)\n local u=((self.gaitPhase or 0)/(math.pi*2))%1;local support=0\n if not reduced and not self.focusPose and not self.gardenFocus then\n  if u>.08 and u<.50 then support=-math.sin((u-.08)/.42*math.pi)\n  elseif u>.58 then support=math.sin((u-.58)/.42*math.pi)end\n end\n support*=gait\n local weightX=support*.045*math.min(1,(self.worldScale or .72)/.72)\n local weightRoll=support*math.rad(3)\n self.weightShift,self.weightRoll=weightX,weightRoll\n local hipAnchor=v(self.definition.anchors.Body)*self.scale\n local upper=root*CFrame.new(weightX,0,0)*CFrame.new(hipAnchor)*CFrame.Angles(0,0,weightRoll)*CFrame.new(-hipAnchor)\n local hop=(greet*.11+(self.movementBob or 0))*self.scale\n local headAnchor=v(self.definition.anchors.Head)*self.scale\n local head=upper*CFrame.new(0,hop+(pose.head+breath)*self.scale,0)*CFrame.new(headAnchor)*CFrame.Angles(-greet*.08+shove*.15+headPitch,headYaw,pose.tilt+(self.affectionTilt or 0)*.08)*CFrame.new(-headAnchor)\n Bounds.begin(self);Bounds.begin(self.bodyHull)\n for _,entry in ipairs(self.pieces)do\n  local name,channel=entry.name,entry.channel;local part=entry.part\n  local cf=upper*CFrame.new(0,hop,0)*entry.frame\n  local isFace=channel==\"Face\"or string.find(name,\"Eye\")or string.find(name,\"Glint\")or string.find(name,\"Mouth\")or string.find(name,\"Teeth\")or string.find(name,\"Cheek\")\n  if channel==\"Head\"or isFace or channel==\"Charm\"then cf=head*entry.frame end\n  if channel==\"HandL\"or channel==\"HandR\"or channel==\"CuffL\"or channel==\"CuffR\"or channel==\"Hand\"then\n   local side=if string.sub(name,-1)==\"L\"then -1 else 1\n   local anchorName=(if string.find(channel,\"^Cuff\")then \"Cuff\"else \"Hand\")..(if side<0 then \"L\"else \"R\")\n   local anchor=v(self.definition.anchors[anchorName]or self.definition.anchors[if side<0 then \"HandL\"else \"HandR\"])*self.scale\n   local fold=pose.hand+greet*.5+shove*.7\n   cf=upper*CFrame.new(0,hop,0)*CFrame.new(anchor)*CFrame.Angles(-fold,0,side*(-fold*.38+step*.18))*CFrame.new(-anchor)*entry.frame\n  elseif channel==\"FootL\"or channel==\"FootR\"or channel==\"Foot\"then\n   local side=if string.sub(name,-1)==\"L\"then -1 else 1\n   cf=root*CFrame.new(0,math.max(0,step*side)*.045*self.scale,step*side*.075*self.scale)*entry.frame\n  end\n  local size=entry.size;local hidden=not Charms.isVisible(self,entry)\n  if channel==\"Body\"then\n   local squash=if self.petId==\"pip\"then math.cos((self.gaitPhase or 0)*2)*gait*.018 else 0\n   size=Vector3.new(size.X*(1+squash*.35),size.Y*(1+bodyStretch-squash),size.Z*(1+squash*.35))\n  end\n  if entry.role==\"charm\"then cf,size=Charms.pose(self,cf,size,dotX,dotY,dotStretch)end\n  if string.find(name,\"Eye\")then size=Vector3.new(size.X*(if pose.mouth==\"open\"then 1.12 else 1),size.Y*pose.eye*blink,size.Z)\n  elseif string.find(name,\"Glint\")then hidden=hidden or pose.eye*blink<.4\n  elseif name==\"MouthO\"then hidden=hidden or pose.mouth~=\"open\"\n  elseif name==\"MouthSmile\"then\n   hidden=hidden or pose.mouth==\"open\"\n   if pose.mouth==\"line\"then size=Vector3.new(size.X*.5,size.Y*.24,size.Z)elseif pose.mouth==\"soft\"then size=Vector3.new(size.X*.82,size.Y*.75,size.Z)end\n  elseif name==\"Teeth\"or string.find(name,\"^Teeth\")then\n   hidden=hidden or pose.mouth==\"open\"or pose.mouth==\"line\"\n   if pose.mouth==\"soft\"then size*=.78 end\n  end\n  if(name==\"EyeL\"or name==\"EyeR\"or name==\"GlintL\"or name==\"GlintR\")and self.expression==\"curious\"then cf*=CFrame.new(.018*self.scale,.01*self.scale,0)end\n  Face.paintSurface(entry,self,daylight)\n  if entry.faceRole then\n   local tint=if entry.faceRole==\"cheek\"then entry.color:Lerp(self.colors.blush,math.clamp(pose.blush+(self.affectionBlush or 0),0,1))else nil\n   Face.paint(entry,self.worldContext,tint,daylight)\n  end\n  local transparency=if hidden then 1 else 0\n  if entry.lastSize~=size then part.Size=size;entry.lastSize=size end\n  if entry.lastFrame~=cf then part.CFrame=cf;entry.lastFrame=cf end\n  if entry.lastTransparency~=transparency then part.Transparency=transparency;entry.lastTransparency=transparency end\n  if not hidden then\n   Bounds.include(self,cf,size)\n   if entry.role~=\"charm\"then Bounds.include(self.bodyHull,cf,size)end\n  end\n end\n Bounds.finish(self);Bounds.finish(self.bodyHull)\n self.bodyBoundsFrame,self.bodyBoundsSize=self.bodyHull.rigBoundsFrame,self.bodyHull.rigBoundsSize\nend\nfunction Visual:destroy()self.model:Destroy()end\nreturn Visual\n","client/PetIdleMotion":"-- Analytic cosmetics sampled by the existing renderer owner. No tasks or clocks.\nlocal Motion={Version=1,Breath=.014,BodyStretch=.012,HeadAngle=math.rad(2),DotRise=.045,DotSide=.018,DotStretch=.04}\nlocal tau=math.pi*2\nlocal function smooth(t)return t*t*(3-2*t)end\nlocal function seedOf(visual)\n local seed=visual.cosmeticSeed or 0\n local rig=if visual.definition and visual.definition.id==\"ovelle\"then 317 else 0\n return ((math.abs(seed)+rig)%997)/997\nend\nlocal function glance(time)\n local cycle=math.floor(time/10.4);local phase=time%10.4\n local amount=if phase<3.2 then 0 elseif phase<5.6 then smooth((phase-3.2)/2.4)elseif phase<8 then 1 else 1-smooth((phase-8)/2.4)\n return amount*(if cycle%2==0 then 1 else -1)\nend\nfunction Motion.sample(visual,expression)\n if visual.reducedEffects or visual.idleMotionFrozen then return 1,0,0,0,0,0,0,1 end\n local seed=seedOf(visual)\n local time=(visual.cosmeticTime or visual.time or 0)+seed*17.3\n local breath=math.sin(time*tau/3.2)\n local look=glance(time)\n local blink=1\n if expression~=\"sleepy\"and expression~=\"affectionate\"then\n  local phase=(time+seed*2.7)%(3.2+seed*2.2)\n  if phase<.055 then blink=1-.94*smooth(phase/.055)\n  elseif phase<.09 then blink=.06\n  elseif phase<.15 then blink=.06+.94*smooth((phase-.09)/.06)end\n end\n local dotPhase=(time-.25)*tau/3.2\n local stretch=1+Motion.DotStretch*math.sin(dotPhase+math.pi*.5)\n return blink,breath*Motion.Breath,breath*Motion.BodyStretch,look*Motion.HeadAngle,look*Motion.HeadAngle*.5,\n  math.sin(dotPhase*.5)*Motion.DotSide,math.sin(dotPhase)*Motion.DotRise,stretch\nend\n-- Conservative per-axis displacement beyond an actual expression/greeting box.\n-- Includes rotation of each corner, breathing and Dot's independent translation.\nfunction Motion.padding(visual,entry)\n local scale=visual.scale or 1\n if entry.channel==\"Body\"then return Vector3.new(0,entry.size.Y*Motion.BodyStretch*.5,0)end\n local name=entry.name\n local head=entry.channel==\"Head\"or entry.channel==\"Face\"or entry.channel==\"Charm\"\n  or string.find(name,\"Eye\")or string.find(name,\"Glint\")or string.find(name,\"Mouth\")or string.find(name,\"Teeth\")or string.find(name,\"Cheek\")\n if not head then return Vector3.zero end\n local anchor=visual.definition.anchors.Head\n local pivot=Vector3.new(anchor[1],anchor[2],anchor[3])*scale\n local radius=(entry.frame.Position-pivot).Magnitude+entry.size.Magnitude*.5\n local turn=2*radius*math.sin(Motion.HeadAngle*1.5*.5)\n local pad=Vector3.new(turn,turn+Motion.Breath*scale,turn)\n if entry.role==\"charm\"then\n  local diameter=math.max(entry.size.X,entry.size.Y,entry.size.Z)\n  local squash=diameter*Motion.DotStretch*.55\n  -- The authored Dot frame also follows the expression's head tilt.\n  pad+=Vector3.one*((Motion.DotSide+Motion.DotRise)*scale+squash)\n end\n return pad\nend\nreturn Motion\n","client/PetExpression":"-- Six original readable poses; no authority, sound, or independent clock.\nlocal Expression={}\nlocal poses={\n neutral={eye=1,mouth=\"smile\",tilt=0,hand=0,head=0,blush=0},\n curious={eye=1.16,mouth=\"smile\",tilt=.14,hand=.16,head=.025,blush=0},\n startled={eye=1.36,mouth=\"open\",tilt=-.035,hand=-.34,head=.07,blush=0},\n pleased={eye=.58,mouth=\"smile\",tilt=-.065,hand=.3,head=.035,blush=.3},\n sleepy={eye=.18,mouth=\"line\",tilt=.11,hand=-.12,head=-.06,blush=.05},\n affectionate={eye=.12,mouth=\"soft\",tilt=-.08,hand=.48,head=-.025,blush=.8},\n}\nfunction Expression.get(name)return poses[name]or poses.neutral end\nfunction Expression.name(visual)\n if visual.petting or(visual.affection or 0)>.15 then return \"affectionate\"end\n return if poses[visual.expression]then visual.expression else \"neutral\"\nend\nExpression.poses=table.freeze(poses)\nreturn Expression\n"},"manifest":[{"path":"src/client/BonusPetVisual.lua","originalSHA256":"af794cb70d64e30b5b29bede859887c74f865ab171ea9300a2c30ce341d713bd","sandboxSHA256":"af794cb70d64e30b5b29bede859887c74f865ab171ea9300a2c30ce341d713bd"},{"path":"src/client/GardenPetVisual.lua","originalSHA256":"ebaf66daa6c73b7f0ffca87dc516dd54df8f688f2fb3adaf07ca400c25bfea17","sandboxSHA256":"c1b91d95ffdaad6afaa3311e570f214d9734d33f9df314ca892a46f3c1203c3d"},{"path":"src/client/HollowClock.lua","originalSHA256":"63971bd3e2cafecffe53ce38437af07ba73b449586bebb95e149933d3f7d3fb9","sandboxSHA256":"63971bd3e2cafecffe53ce38437af07ba73b449586bebb95e149933d3f7d3fb9"},{"path":"src/client/LegacyPetAppearance.lua","originalSHA256":"80ddd62a31afb60db035139f1736482ed6ed6e99b0613f7df14cfd1b2d886b8a","sandboxSHA256":"793a903e731ede7eac6f369ba1f88d354b6ed27e97118cc31eec5730cfc5e692"},{"path":"src/client/PetCharms.lua","originalSHA256":"b0db56c66bea2266701f0bb9a38216b5fb560f68cc9a5da6e54db65af7145b8b","sandboxSHA256":"b0db56c66bea2266701f0bb9a38216b5fb560f68cc9a5da6e54db65af7145b8b"},{"path":"src/client/PetExpression.lua","originalSHA256":"6412b5e0497b50884c5de5aaff5157024827a9b17f89b31861d3dec50f140757","sandboxSHA256":"6412b5e0497b50884c5de5aaff5157024827a9b17f89b31861d3dec50f140757"},{"path":"src/client/PetFace.lua","originalSHA256":"42399be02a298db59cb3dc619f02980922833a5e7e59abcd0ef58215ff6e7581","sandboxSHA256":"42399be02a298db59cb3dc619f02980922833a5e7e59abcd0ef58215ff6e7581"},{"path":"src/client/PetFactory.lua","originalSHA256":"9b3430bc136b5780bafd